    return { ok: false, completed: 0, reason: "storage de Planning no disponible" };
  const resolved = await resolvePlanningScope(input.sessionID, options);
  if (!resolved)
    return { ok: false, completed: 0, reason: "sesión/proyecto no evaluable" };
